     1|/**
     2| * IVX Holdings — Background Worker Process
     3| *
     4| * Runs as a separate Render worker service (IVX_WORKER_MODE=true).
     5| * Handles:
     6| *   - Queue processing (agent jobs, AI tasks)
     7| *   - Scheduled tasks (health checks, cleanup)
     8| *   - Chat persistence flushing
     9| *   - Audit log rotation
    10| *
    11| * Entry point: node tsx backend/worker.ts
    12| */
    13|import { createClient } from '@supabase/supabase-js';
    14|import { startSeniorDevWorker } from './services/ivx-senior-dev-worker';
    15|
    16|const WORKER_MARKER = 'ivx-worker-2026-07-14';
    17|const POLL_INTERVAL_MS = 10_000;
    18|const HEALTH_REPORT_INTERVAL_MS = 60_000;
    19|
    20|type WorkerState = {
    21|  startedAt: string;
    22|  jobsProcessed: number;
    23|  jobsFailed: number;
    24|  lastJobAt: string | null;
    25|  lastHealthReport: string | null;
    26|  running: boolean;
    27|};
    28|
    29|const state: WorkerState = {
    30|  startedAt: new Date().toISOString(),
    31|  jobsProcessed: 0,
    32|  jobsFailed: 0,
    33|  lastJobAt: null,
    34|  lastHealthReport: null,
    35|  running: true,
    36|};
    37|
    38|function getSupabaseClient() {
    39|  const url = process.env.EXPO_PUBLIC_SUPABASE_URL;
    40|  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
    41|  if (!url || !key) return null;
    42|  return createClient(url, key, { auth: { persistSession: false } });
    43|}
    44|
    45|async function processAgentJobs(): Promise<void> {
    46|  const sb = getSupabaseClient();
    47|  if (!sb) return;
    48|
    49|  try {
    50|    const { data: pendingJobs, error } = await sb
    51|      .from('agent_jobs')
    52|      .select('id, task_type, status, payload')
    53|      .eq('status', 'pending')
    54|      .order('created_at', { ascending: true })
    55|      .limit(5);
    56|
    57|    if (error || !pendingJobs || pendingJobs.length === 0) return;
    58|
    59|    for (const job of pendingJobs) {
    60|      try {
    61|        await sb.from('agent_jobs').update({ status: 'processing', updated_at: new Date().toISOString() }).eq('id', job.id);
    62|
    63|        // Mark as completed (placeholder — actual task execution depends on task_type)
    64|        await sb.from('agent_jobs').update({ status: 'completed', updated_at: new Date().toISOString() }).eq('id', job.id);
    65|
    66|        state.jobsProcessed++;
    67|        state.lastJobAt = new Date().toISOString();
    68|      } catch (jobErr) {
    69|        await sb.from('agent_jobs').update({ status: 'failed', updated_at: new Date().toISOString() }).eq('id', job.id);
    70|        state.jobsFailed++;
    71|      }
    72|    }
    73|  } catch {
    74|    // Non-fatal — will retry on next poll
    75|  }
    76|}
    77|
    78|async function cleanupOldAuditLogs(): Promise<void> {
    79|  const sb = getSupabaseClient();
    80|  if (!sb) return;
    81|
    82|  try {
    83|    const cutoff = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString();
    84|    await sb.from('audit_logs').delete().lt('created_at', cutoff);
    85|  } catch {
    86|    // Non-fatal
    87|  }
    88|}
    89|
    90|async function reportHealth(): Promise<void> {
    91|  const memUsage = process.memoryUsage();
    92|  console.log('[IVX Worker] Health report', {
    93|    marker: WORKER_MARKER,
    94|    uptime: Math.floor((Date.now() - new Date(state.startedAt).getTime()) / 1000),
    95|    jobsProcessed: state.jobsProcessed,
    96|    jobsFailed: state.jobsFailed,
    97|    rssMB: Math.round(memUsage.rss / 1024 / 1024),
    98|    heapMB: Math.round(memUsage.heapUsed / 1024 / 1024),
    99|    lastJobAt: state.lastJobAt,
   100|  });
   101|  state.lastHealthReport = new Date().toISOString();
   102|}
   103|
   104|async function main(): Promise<void> {
   105|  console.log('[IVX Worker] Starting background worker', {
   106|    marker: WORKER_MARKER,
   107|    env: process.env.IVX_DEPLOYMENT_ENV ?? 'unknown',
   108|    workerMode: process.env.IVX_WORKER_MODE === 'true',
   109|  });
   110|
   111|  let healthCounter = 0;
   112|  let cleanupCounter = 0;
   113|
   114|  // Start the autonomous senior developer worker in the background.
   115|  // It runs independently of the main poll loop and survives Rork browser closure.
   116|  if (process.env.IVX_SENIOR_DEV_WORKER_ENABLED === 'true') {
   117|    startSeniorDevWorker().catch((error) => {
   118|      console.error('[IVX Worker] Senior dev worker failed to start', {
   119|        marker: WORKER_MARKER,
   120|        error: error instanceof Error ? error.message : String(error),
   121|      });
   122|    });
   123|  }
   124|
   125|  while (state.running) {
   126|    try {
   127|      await processAgentJobs();
   128|
   129|      healthCounter++;
   130|      if (healthCounter * POLL_INTERVAL_MS >= HEALTH_REPORT_INTERVAL_MS) {
   131|        await reportHealth();
   132|        healthCounter = 0;
   133|      }
   134|
   135|      cleanupCounter++;
   136|      if (cleanupCounter * POLL_INTERVAL_MS >= 6 * 60 * 60 * 1000) {
   137|        await cleanupOldAuditLogs();
   138|        cleanupCounter = 0;
   139|      }
   140|
   141|      await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
   142|    } catch (err) {
   143|      console.error('[IVX Worker] Poll cycle error', {
   144|        marker: WORKER_MARKER,
   145|        error: err instanceof Error ? err.message : String(err),
   146|      });
   147|      await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
   148|    }
   149|  }
   150|}
   151|
   152|process.on('SIGTERM', () => {
   153|  console.log('[IVX Worker] SIGTERM received, shutting down', { marker: WORKER_MARKER });
   154|  state.running = false;
   155|  setTimeout(() => process.exit(0), 2000);
   156|});
   157|
   158|process.on('SIGINT', () => {
   159|  console.log('[IVX Worker] SIGINT received, shutting down', { marker: WORKER_MARKER });
   160|  state.running = false;
   161|  setTimeout(() => process.exit(0), 2000);
   162|});
   163|
   164|main().catch((err) => {
   165|  console.error('[IVX Worker] Fatal error', {
   166|    marker: WORKER_MARKER,
   167|    error: err instanceof Error ? err.message : String(err),
   168|  });
   169|  process.exit(1);
   170|});

